export const ImageRef = ({ src, width, height }: { src: string, width?: number, height?: number}) => {
    const srcImg = bgImages[src];
    const ratio = srcImg.width / srcImg.height;

    const srcWidth = height ? height * ratio : (width ?? srcImg.width);
    const srcHeight = width ? width / ratio : (height ?? srcImg.height);

    return <Image source={srcImg.uri} resizeMode="contain" style={{ width: srcWidth, height: srcHeight }} />
}

