export default function AntdMiniIcon({ name, size, color = colors.brands1, style }: { name: string, size?: number, color?: string, style?: ViewStyle }) {

    if (iconMapping[name]) {
        return <Text style={{
                fontFamily: 'antdmini-icon',
                fontSize: size,
                color,
                ...style
            }}>
            {iconMapping[name] ?? '\ue66f'}
        </Text>
    }

    if (svgMapping[name]) {
        return <Svg width={size} height={size} viewBox="0 0 24 24" fill={color}>
            {svgMapping[name]}
        </Svg>
    }

    return <View></View>
}